using System.Diagnostics;
using System.Text.RegularExpressions;

namespace Zenkins.Tests.Git;

/// <summary>
/// A <b>real OpenSSH server</b> (<c>sshd</c>) serving a private bare repository on loopback, for card
/// Q-009's acceptance evidence: the SSH half of F-018 stops being shape-pinned and is verified against
/// the binary the product's hardened <c>GIT_SSH_COMMAND</c> actually talks to.
/// <para>
/// <b>The Q-008 precedent: a real dependency in a synthetic environment.</b> Every key this fixture
/// uses is generated by this fixture (<c>ssh-keygen</c> into its own temporary directory), the
/// <c>authorized_keys</c> file is this fixture's own, and the <c>sshd_config</c> points every path at
/// that directory. Nothing on the host's <c>~/.ssh</c> is read, written or depended on; the operator's
/// ssh agent is unreachable because the config allows public-key authentication only and the fixture's
/// <c>authorized_keys</c> holds exactly one key this fixture generated.
/// </para>
/// <para>
/// <b>Non-root by design.</b> <c>sshd</c> runs as the user the tests run as, in the foreground
/// (<c>-D -e</c>), with its own host key, its own pid file and <c>StrictModes no</c> (the fixture's
/// files live in a temporary directory, not a real home). Only that same user can authenticate - the
/// clone URL names <see cref="Environment.UserName"/> - which is exactly the single-account shape a
/// keyless fixture wants. The server logs at <c>VERBOSE</c> level, so "the delivered key is what
/// authenticated" is the server's own observation (accepted key fingerprints) rather than an inference
/// from our side.
/// </para>
/// <para>
/// <b>Lifecycle tracked like every other harness process.</b> The process is started with redirected
/// output, waited for until it reports <c>Server listening on</c>, and <see cref="Dispose"/> kills it
/// as a tree, waits for the exit and records both facts before deleting the temporary root.
/// </para>
/// <para>
/// <b>Two recorded macOS/OpenSSH-10 quirks.</b> First, OpenSSH 9.8+ enables
/// <c>PerSourcePenalties</c> by default: failed authentications would make the source address
/// progressively refused, which is exactly what the rejection-path tests do on purpose, so the config
/// switches the penalties off where the binary supports them (the config is validated with
/// <c>sshd -t</c> and version-unsupported options are dropped, never guessed). Second, a non-root
/// <c>sshd</c> cannot set the BSM audit session on macOS
/// (<c>bsm_audit_session_setup: setaudit_addr failed: Operation not permitted</c>); the line is logged
/// and the session proceeds anyway - a quirk of running unprivileged, not a fixture failure.
/// </para>
/// </summary>
internal sealed class SshdGitServer : IDisposable
{
    private static readonly TimeSpan StartTimeout = TimeSpan.FromSeconds(20);
    private static readonly TimeSpan ShutdownTimeout = TimeSpan.FromSeconds(15);

    private static (string SshdPath, string KeygenPath, string SshPath)? _tools;

    private readonly Process _process;
    private readonly List<string> _log = [];
    private readonly object _logGate = new();
    private readonly string _rootPath;
    private readonly string _pinnedKnownHostsPath;
    private readonly string _wrongKnownHostsPath;
    private bool _disposed;
    private bool _exitedOnDispose;
    private bool _rootRemoved;

    private SshdGitServer(
        string rootPath,
        Process process,
        string repositoryPath,
        string url,
        string deliveredPrivateKey,
        string deliveredKeyPath,
        string rejectedPrivateKey,
        string deliveredKeyFingerprint,
        string rejectedKeyFingerprint,
        string pinnedKnownHostsPath,
        string wrongKnownHostsPath)
    {
        _rootPath = rootPath;
        _process = process;
        RepositoryPath = repositoryPath;
        Url = url;
        DeliveredPrivateKey = deliveredPrivateKey;
        DeliveredKeyPath = deliveredKeyPath;
        RejectedPrivateKey = rejectedPrivateKey;
        DeliveredKeyFingerprint = deliveredKeyFingerprint;
        RejectedKeyFingerprint = rejectedKeyFingerprint;
        _pinnedKnownHostsPath = pinnedKnownHostsPath;
        _wrongKnownHostsPath = wrongKnownHostsPath;
        _process.OutputDataReceived += (_, args) => RecordLog(args.Data);
        _process.ErrorDataReceived += (_, args) => RecordLog(args.Data);
        _process.BeginOutputReadLine();
        _process.BeginErrorReadLine();
    }

    /// <summary>The bare repository this server serves (the worker really clones it).</summary>
    public string RepositoryPath { get; }

    /// <summary>
    /// The clone URL (<c>ssh://{user}@127.0.0.1:{port}{path}</c>). The account is the user running the
    /// tests, because a non-root <c>sshd</c> can authenticate only that user.
    /// </summary>
    public string Url { get; }

    /// <summary>The server process id (a real process, not an in-host instance).</summary>
    public int ProcessId => _process.Id;

    /// <summary>The private key the <b>delivered credential</b> holds (the value the server hands the worker).</summary>
    public string DeliveredPrivateKey { get; }

    /// <summary>Where that key file lives (the control clone's <c>ssh -i</c> names it directly).</summary>
    public string DeliveredKeyPath { get; }

    /// <summary>A valid private key this fixture generated but did <b>not</b> install: what a rejected credential is.</summary>
    public string RejectedPrivateKey { get; }

    /// <summary>The server-visible fingerprint (<c>SHA256:…</c>) of the delivered key.</summary>
    public string DeliveredKeyFingerprint { get; }

    /// <summary>The server-visible fingerprint of the rejected key.</summary>
    public string RejectedKeyFingerprint { get; }

    /// <summary>
    /// A known-hosts file that <b>trusts</b> this server's host key, pinned for the exact
    /// <c>[127.0.0.1]:{port}</c> host - what <c>ZENKINS_GIT_KNOWN_HOSTS</c> points at when a run must
    /// pass strict host-key checking.
    /// </summary>
    public string PinnedKnownHostsPath => _pinnedKnownHostsPath;

    /// <summary>
    /// A known-hosts file that pins a <b>wrong</b> key for the same <c>[127.0.0.1]:{port}</c> host:
    /// the client does not trust this server. Everything else about the setup is identical to
    /// <see cref="PinnedKnownHostsPath"/>, so a refusal with this file is the pin doing its job.
    /// </summary>
    public string WrongKnownHostsPath => _wrongKnownHostsPath;

    /// <summary>Whether <c>Dispose</c> really stopped the server process (the tracked-lifecycle fact).</summary>
    public bool ExitedOnDispose => _exitedOnDispose;

    /// <summary>Whether the temporary root (keys, config, log) is really gone after <see cref="Dispose"/>.</summary>
    public bool RootRemoved => _rootRemoved;

    /// <summary>
    /// Why the sshd suite cannot run on this machine, or <see langword="null"/> when it can. The tests
    /// skip with this reason - a recorded, named skip, never a silent one.
    /// </summary>
    public static string? UnavailabilityReason()
    {
        if (OperatingSystem.IsWindows())
        {
            return "the GitSshd suite runs a real OpenSSH sshd as a user process; Windows ships no sshd "
                + "by default (the optional OpenSSH Server feature would have to be installed), so the "
                + "suite is not runnable there.";
        }

        return ResolveTools() is null
            ? "no OpenSSH tools were found: the suite needs `sshd` and `ssh-keygen` on PATH or at the "
            + "standard locations (/usr/sbin/sshd, /usr/bin/ssh-keygen, /usr/bin/ssh)."
            : null;
    }

    /// <summary>The ssh client binary the recording shim execs (resolved by <see cref="UnavailabilityReason"/>).</summary>
    public static string SshClientPath
    {
        get
        {
            var tools = ResolveTools()
                ?? throw new InvalidOperationException(
                    "no OpenSSH tools found on this machine; check UnavailabilityReason() first.");
            return tools.SshPath;
        }
    }

    /// <summary>
    /// Starts a real <c>sshd</c> over <paramref name="bareRepositoryPath"/>: generates the host key and
    /// two client keys, writes the <c>authorized_keys</c> file and the config, validates the config
    /// with <c>sshd -t</c> (dropping version-unsupported options), and waits for
    /// <c>Server listening on</c>.
    /// </summary>
    public static SshdGitServer Start(string bareRepositoryPath)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(bareRepositoryPath);
        var tools = ResolveTools()
            ?? throw new InvalidOperationException(
                "sshd/ssh-keygen were not found on this machine; check UnavailabilityReason() first.");
        var (sshdPath, keygenPath, _) = tools;

        var root = Path.Combine(Path.GetTempPath(), $"zenkins-q009-sshd-{Guid.NewGuid():N}");
        Directory.CreateDirectory(root);

        // The keys: one host key for the server, one client key the DELIVERED credential will hold,
        // one client key that stays unrecognized (the rejected credential), and one extra key whose
        // public half stands in for "a host key the client does not trust".
        GenerateKey(keygenPath, root, "host_ed25519", "zenkins-q009-host");
        GenerateKey(keygenPath, root, "delivered_ed25519", "zenkins-q009-delivered");
        GenerateKey(keygenPath, root, "rejected_ed25519", "zenkins-q009-rejected");
        GenerateKey(keygenPath, root, "other-host_ed25519", "zenkins-q009-other-host");

        // authorized_keys: exactly one key - the delivered one. StrictModes is off (the fixture's files
        // are not a real home), but the file still gets 0600: what a real deployment would do.
        var authorizedKeysPath = Path.Combine(root, "authorized_keys");
        File.WriteAllText(authorizedKeysPath, File.ReadAllText(Path.Combine(root, "delivered_ed25519.pub")));
        if (!OperatingSystem.IsWindows())
        {
            File.SetUnixFileMode(
                authorizedKeysPath,
                System.IO.UnixFileMode.UserRead | System.IO.UnixFileMode.UserWrite);
        }

        var deliveredFingerprint = ReadFingerprint(keygenPath, Path.Combine(root, "delivered_ed25519.pub"));
        var rejectedFingerprint = ReadFingerprint(keygenPath, Path.Combine(root, "rejected_ed25519.pub"));

        var deliveredPrivateKey = File.ReadAllText(Path.Combine(root, "delivered_ed25519"));
        var rejectedPrivateKey = File.ReadAllText(Path.Combine(root, "rejected_ed25519"));

        for (var attempt = 0; attempt < 5; attempt++)
        {
            var port = FindFreePort();
            var configPath = Path.Combine(root, "sshd_config");
            // WriteConfig happens inside ValidateAndRepair: it rewrites the file every time it drops a
            // version-unsupported option, so the file on disk is always the config that was validated.
            ValidateAndRepair(sshdPath, configPath, ConfigLines(port, root, authorizedKeysPath));

            // From the moment the process exists, nothing may leak it: a constructor throw, a
            // listener timeout or the bind race all end in a waited kill (the tracked-lifecycle
            // discipline applies to Start's own failure paths, not only to Dispose).
            var process = StartSshd(sshdPath, configPath);
            SshdGitServer? server = null;
            var listening = false;
            try
            {
                var pinnedPath = WriteKnownHosts(
                    Path.Combine(root, "known_hosts.pinned"), port, Path.Combine(root, "host_ed25519.pub"));
                var wrongPath = WriteKnownHosts(
                    Path.Combine(root, "known_hosts.wrong"), port, Path.Combine(root, "other-host_ed25519.pub"));

                server = new SshdGitServer(
                    root,
                    process,
                    bareRepositoryPath,
                    $"ssh://{Environment.UserName}@127.0.0.1:{port}{bareRepositoryPath}",
                    deliveredPrivateKey,
                    Path.Combine(root, "delivered_ed25519"),
                    rejectedPrivateKey,
                    deliveredFingerprint,
                    rejectedFingerprint,
                    pinnedPath,
                    wrongPath);

                listening = server.AwaitListener();
                if (listening)
                {
                    return server;
                }

                // The port was taken between the probe and the bind (sshd says so and exits); try
                // another. The temporary root is deliberately kept: the next attempt reuses the keys.
            }
            finally
            {
                if (!listening)
                {
                    if (server is not null)
                    {
                        server.DetachAndKill();
                    }
                    else
                    {
                        KillProcess(process);
                    }
                }
            }
        }

        throw new InvalidOperationException("The sshd fixture could not bind a loopback port.");
    }

    /// <summary>Every accepted public-key authentication, as the server logged it (fingerprints only).</summary>
    public string[] AcceptedFingerprints =>
        LogLines()
            .Where(line => line.StartsWith("Accepted publickey", StringComparison.Ordinal))
            .Select(FingerprintOf)
            .ToArray();

    /// <summary>How many public-key authentications the server has accepted so far.</summary>
    public int AcceptedPublicKeyCount => AcceptedFingerprints.Length;

    /// <summary>Every public-key offer the server refused, as the server logged it (fingerprints only).</summary>
    public string[] RefusedFingerprints =>
        LogLines()
            .Where(line => line.StartsWith("Failed publickey", StringComparison.Ordinal))
            .Select(FingerprintOf)
            .ToArray();

    /// <summary>The server's log lines so far (the VERBOSE auth record the counters are read from).</summary>
    public string[] LogSnapshot()
    {
        lock (_logGate)
        {
            return [.. _log];
        }
    }

    public void Dispose()
    {
        if (_disposed)
        {
            return;
        }

        _disposed = true;
        _exitedOnDispose = KillProcess(_process);
        _rootRemoved = DeleteDirectory(_rootPath);
    }

    // -------------------------------------------------------------------------------------------

    private void RecordLog(string? line)
    {
        if (line is null)
        {
            return;
        }

        lock (_logGate)
        {
            _log.Add(line);
        }
    }

    private string[] LogLines()
    {
        lock (_logGate)
        {
            return [.. _log];
        }
    }

    private static string FingerprintOf(string line)
    {
        var at = line.IndexOf("SHA256:", StringComparison.Ordinal);
        return at < 0 ? string.Empty : line[at..].Trim();
    }

    private static (string SshdPath, string KeygenPath, string SshPath)? ResolveTools()
    {
        if (_tools is { } memoized)
        {
            return memoized;
        }

        var sshd = FindTool("sshd", "/usr/sbin/sshd");
        var keygen = FindTool("ssh-keygen", "/usr/bin/ssh-keygen");
        var ssh = FindTool("ssh", "/usr/bin/ssh");
        if (sshd is null || keygen is null || ssh is null)
        {
            return null;
        }

        _tools = (sshd, keygen, ssh);
        return _tools;
    }

    private static string? FindTool(string name, string standardLocation)
    {
        var path = Environment.GetEnvironmentVariable("PATH") ?? string.Empty;
        foreach (var directory in path.Split(Path.PathSeparator))
        {
            if (string.IsNullOrWhiteSpace(directory))
            {
                continue;
            }

            var candidate = Path.Combine(directory, name);
            if (File.Exists(candidate))
            {
                return candidate;
            }
        }

        return File.Exists(standardLocation) ? standardLocation : null;
    }

    private static void GenerateKey(string keygenPath, string root, string fileName, string comment)
    {
        var (exitCode, _, standardError) = RunCapture(
            keygenPath,
            ["-q", "-t", "ed25519", "-N", "", "-f", Path.Combine(root, fileName), "-C", comment]);
        if (exitCode != 0)
        {
            throw new InvalidOperationException($"ssh-keygen could not generate {fileName}: {standardError}");
        }
    }

    private static string ReadFingerprint(string keygenPath, string publicKeyPath)
    {
        var (exitCode, standardOutput, standardError) = RunCapture(keygenPath, ["-lf", publicKeyPath]);
        if (exitCode != 0)
        {
            throw new InvalidOperationException($"ssh-keygen could not fingerprint {publicKeyPath}: {standardError}");
        }

        // "256 SHA256:<base64> comment (ED25519)"
        var parts = standardOutput.Trim().Split(' ', StringSplitOptions.RemoveEmptyEntries);
        return parts.Length > 1 && parts[1].StartsWith("SHA256:", StringComparison.Ordinal)
            ? parts[1]
            : throw new InvalidOperationException($"unexpected ssh-keygen fingerprint output: {standardOutput}");
    }

    private static string WriteKnownHosts(string path, int port, string publicKeyPath)
    {
        // "[host]:port keytype base64" - the spelling a non-standard port requires.
        var body = File.ReadAllText(publicKeyPath).Trim().Split(' ', StringSplitOptions.RemoveEmptyEntries)[1];
        File.WriteAllText(path, $"[127.0.0.1]:{port} ssh-ed25519 {body}\n");
        return path;
    }

    private static List<string> ConfigLines(int port, string root, string authorizedKeysPath) =>
    [
        $"Port {port}",
        "ListenAddress 127.0.0.1",
        $"HostKey {Path.Combine(root, "host_ed25519")}",
        $"PidFile {Path.Combine(root, "sshd.pid")}",
        "StrictModes no",
        "PubkeyAuthentication yes",
        "PasswordAuthentication no",
        "KbdInteractiveAuthentication no",
        "UsePAM no",
        $"AuthorizedKeysFile {authorizedKeysPath}",
        "LogLevel VERBOSE",
        "PerSourcePenalties no",
        "AuthenticationMethods publickey",
        "PermitTTY no",
        "X11Forwarding no",
        "AllowTcpForwarding no",
        "AllowAgentForwarding no",
        "PrintMotd no",
    ];

    /// <summary>
    /// Validates the config with <c>sshd -t</c> and, when the local OpenSSH does not know an option,
    /// drops exactly the option it named and retries - so the fixture never guesses which knobs a
    /// given OpenSSH version supports. Anything else is a loud failure with the server's own stderr.
    /// </summary>
    private static List<string> ValidateAndRepair(string sshdPath, string configPath, List<string> lines)
    {
        for (var attempt = 0; attempt < 8; attempt++)
        {
            File.WriteAllLines(configPath, lines);
            var (exitCode, _, standardError) = RunCapture(sshdPath, ["-t", "-f", configPath]);
            if (exitCode == 0)
            {
                return lines;
            }

            var match = Regex.Match(
                standardError,
                @"Bad configuration option:\s*(?<name>\S+)",
                RegexOptions.CultureInvariant);
            if (!match.Success)
            {
                throw new InvalidOperationException(
                    $"sshd rejected the fixture config (exit {exitCode}): {standardError}");
            }

            var option = match.Groups["name"].Value;
            lines = lines
                .Where(line => !string.Equals(
                    line.Split(' ', StringSplitOptions.RemoveEmptyEntries).FirstOrDefault(),
                    option,
                    StringComparison.OrdinalIgnoreCase))
                .ToList();
        }

        throw new InvalidOperationException("sshd kept rejecting the fixture config after dropping the named options.");
    }

    private static Process StartSshd(string sshdPath, string configPath)
    {
        var startInfo = new ProcessStartInfo
        {
            FileName = sshdPath,
            UseShellExecute = false,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            CreateNoWindow = true,
        };
        foreach (var argument in new[] { "-D", "-e", "-f", configPath })
        {
            startInfo.ArgumentList.Add(argument);
        }

        return Process.Start(startInfo)
            ?? throw new InvalidOperationException("The sshd process could not be started.");
    }

    /// <summary>
    /// Waits for the server's own <c>Server listening on</c> line (or an early exit).
    /// <see langword="false"/> means the process is gone and the caller should retry.
    /// </summary>
    private bool AwaitListener()
    {
        var deadline = DateTime.UtcNow + StartTimeout;
        while (DateTime.UtcNow < deadline)
        {
            var snapshot = LogLines();
            if (snapshot.Any(line => line.Contains("Server listening on", StringComparison.Ordinal)))
            {
                return true;
            }

            try
            {
                if (_process.HasExited)
                {
                    return false;
                }
            }
            catch (InvalidOperationException)
            {
                return false;
            }

            Thread.Sleep(100);
        }

        throw new InvalidOperationException(
            "sshd never reported `Server listening on` within "
            + $"{StartTimeout.TotalSeconds:0}s: {string.Join(Environment.NewLine, LogLines())}");
    }

    /// <summary>
    /// Kills the server process without the full cleanup, for the bind-retry loop (the generated keys
    /// and config survive for the next attempt; the half-built instance is discarded by the caller).
    /// </summary>
    private void DetachAndKill() => KillProcess(_process);

    private static bool KillProcess(Process process)
    {
        try
        {
            if (!process.HasExited)
            {
                process.Kill(entireProcessTree: true);
            }

            return process.WaitForExit((int)ShutdownTimeout.TotalMilliseconds) && process.HasExited;
        }
        catch (Exception failure) when (failure is InvalidOperationException or SystemException)
        {
            // Already gone: the tracked-lifecycle goal (nothing left running) is met.
            return true;
        }
        finally
        {
            process.Dispose();
        }
    }

    private static bool DeleteDirectory(string path)
    {
        // Q-011's cleanup contract via TestCleanup: the served roots hold git repositories with
        // read-only pack files, which a Windows delete can only pass once the attribute is cleared.
        return TestCleanup.DeleteTree(path);
    }

    private static int FindFreePort()
    {
        using var probe = new System.Net.Sockets.TcpListener(System.Net.IPAddress.Loopback, 0);
        probe.Start();
        var port = ((System.Net.IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();
        return port;
    }

    private static (int ExitCode, string StandardOutput, string StandardError) RunCapture(
        string fileName, IReadOnlyList<string> arguments)
    {
        var startInfo = new ProcessStartInfo
        {
            FileName = fileName,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true,
        };
        foreach (var argument in arguments)
        {
            startInfo.ArgumentList.Add(argument);
        }

        using var process = Process.Start(startInfo)
            ?? throw new InvalidOperationException($"{fileName} could not be started.");
        var standardOutput = process.StandardOutput.ReadToEnd();
        var standardError = process.StandardError.ReadToEnd();
        process.WaitForExit();
        return (process.ExitCode, standardOutput, standardError);
    }
}
